style.css:
/* Standard syntax for modern browsers */
::placeholder {
  color: #999; /* Light gray color */
  font-style: italic;
  font-size: 0.9em;
  text-transform: capitalize;
  letter-spacing: 0.5px;
}

/* Vendor prefixes for older browser compatibility */
::-webkit-input-placeholder { /* Chrome, Safari, Opera */
  color: #999;
  font-style: italic;
  font-size: 0.9em;
  text-transform: capitalize;
  letter-spacing: 0.5px;
}

:-moz-placeholder { /* Firefox 18- */
  color: #999;
  font-style: italic;
  font-size: 0.9em;
  text-transform: capitalize;
  letter-spacing: 0.5px;
}

::-moz-placeholder { /* Firefox 19+ */
  color: #999;
  font-style: italic;
  font-size: 0.9em;
  text-transform: capitalize;
  letter-spacing: 0.5px;
  opacity: 1; /* Override Firefox's default lower opacity */
}

:-ms-input-placeholder { /* IE 10+ */
  color: #999;
  font-style: italic;
  font-size: 0.9em;
  text-transform: capitalize;
  letter-spacing: 0.5px;
}
